QWidget *conditionTools(QLineEdit *source,std::function<Project()> provider){auto *widget=new QWidget;auto *row=new QHBoxLayout(widget);row->setContentsMargins(0,0,0,0);row->addWidget(source,1);auto *button=new QPushButton("Condition…");row->addWidget(button);QObject::connect(button,&QPushButton::clicked,widget,[source,provider]{auto project=provider();QDialog dialog(source);dialog.setWindowTitle("Choice condition");auto *form=new QFormLayout(&dialog);auto *type=new QComboBox;type->addItems({"Always enabled","Variable","Item count"});auto *variable=new QComboBox,*storage=new QComboBox,*item=new QComboBox,*compare=new QComboBox,*value=new QComboBox;for(auto &v:project.variables)variable->addItem(v.id);variable->addItem("result");for(auto &s:project.storages)storage->addItem(s.name,s.id);for(auto &i:project.items)item->addItem(i.name,i.id);compare->addItems({"==","!=","<","<=",">",">="});value->setEditable(true);value->addItems({"1","0"});for(auto &v:project.variables)value->addItem(v.id);value->addItem("result");form->addRow("Test",type);form->addRow("Variable",variable);form->addRow("Storage",storage);form->addRow("Item",item);form->addRow("Comparison",compare);form->addRow("Value / variable",value);CFCondition old{};QString error;GameCompiler(project).condition(source->text(),old,error);type->setCurrentIndex(old.type);if(old.type==1)variable->setCurrentIndex(old.a==31?project.variables.size():old.a);if(old.type==2){storage->setCurrentIndex(old.a);item->setCurrentIndex(old.b);}compare->setCurrentIndex(old.compare);if(old.rhs_variable)value->setCurrentText(old.value==31?"result":project.variables.value(old.value).id);else value->setCurrentText(QString::number(old.value));auto update=[=]{variable->setEnabled(type->currentIndex()==1);storage->setEnabled(type->currentIndex()==2);item->setEnabled(type->currentIndex()==2);compare->setEnabled(type->currentIndex()!=0);value->setEnabled(type->currentIndex()!=0);};QObject::connect(type,&QComboBox::currentIndexChanged,&dialog,update);update();auto *status=new QLabel;form->addRow(status);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form->addRow(buttons);QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{QString test;if(type->currentIndex()==1)test=variable->currentText()+" "+compare->currentText()+" "+value->currentText();if(type->currentIndex()==2)test="has "+storage->currentData().toString()+" "+item->currentData().toString()+" "+compare->currentText()+" "+value->currentText();CFCondition c{};QString error;if(!GameCompiler(project).condition(test,c,error)){status->setText(error);return;}source->setText(test);dialog.accept();});dialog.exec();});return widget;}
QWidget *eventTools(QPlainTextEdit *source,std::function<Project()> provider){auto *widget=new QWidget;auto *layout=new QVBoxLayout(widget);layout->setContentsMargins(0,0,0,0);auto *row=new QHBoxLayout;auto *insert=new QPushButton("+ Event…"),*condition=new QPushButton("+ If…"),*check=new QPushButton("Check script");row->addWidget(insert);row->addWidget(condition);row->addWidget(check);row->addStretch();layout->addLayout(row);layout->addWidget(source);
auto open=[source,provider](bool branch){auto project=provider();QDialog dialog(source);dialog.setWindowTitle("Insert event");dialog.resize(580,360);auto *root=new QVBoxLayout(&dialog);auto *command=new QComboBox;QStringList keys{"set","add","sub","random","seed","give","take","move","open","view","dialogue","resume","call","timer","if","if has","else","end","scene","area","object","npc","sound play","sound loop","sound stop","menu","return","keyboard","save write","save read","save check","save erase","text clear","text copy"};command->addItems({"Variables / Set","Variables / Add","Variables / Subtract","RNG / Random range","RNG / Set seed","Items / Give","Items / Take","Items / Transfer","Storage / Open","Storage / Inspect","Dialogue / Show prompt","Dialogue / Return to world","Scripts / Call","Timing / Control timer","Conditions / Variable comparison","Conditions / Item count","Conditions / Else","Conditions / End","Scenes / Load scene","Areas / Load area","Objects / Call event","NPCs / Call event","Sound / Play one-shot","Sound / Start loop","Sound / Stop all","Menus / Open menu","Menus / Return","Input / Keyboard","Saves / Write slot","Saves / Load slot","Saves / Check slot","Saves / Erase slot","Text / Clear field","Text / Copy field"});root->addWidget(command);auto *form=new QFormLayout;root->addLayout(form);auto *hint=new QLabel;hint->setWordWrap(true);root->addWidget(hint);root->addStretch();auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);root->addWidget(buttons);QVector<QComboBox *> fields;
auto fill=[&]{while(form->rowCount())form->removeRow(0);fields.clear();QString key=keys[command->currentIndex()];auto field=[&](QString label,QString type){auto *combo=new QComboBox;bool editable=type=="value"||type=="bound"||type=="seed"||type=="limit";combo->setEditable(editable);if(editable){combo->addItem(type=="seed"?"44257":type=="limit"?"12":"1");if(type=="value"||type=="seed"){for(auto &v:project.variables)combo->addItem(v.id);combo->addItem("result");}}else if(type=="variable"||type=="readVariable"){for(auto &v:project.variables)combo->addItem(v.id);if(type=="readVariable")combo->addItem("result");}else if(type=="storage")for(auto &s:project.storages)combo->addItem(s.name+"  ["+s.id+"]",s.id);else if(type=="item")for(auto &i:project.items)combo->addItem(i.name+"  ["+i.id+"]",i.id);else if(type=="prompt")for(auto &p:project.prompts)combo->addItem(p.title+"  ["+p.id+"]",p.id);else if(type=="area")for(auto &a:project.runtimeAreas())combo->addItem(a.name+" ["+a.id+"]",a.id);else if(type=="objectRef"||type=="npcRef")for(auto &a:project.allAreas()){if(type=="objectRef")for(auto &o:a.objects)combo->addItem(a.name+" / "+o.name,a.id+" "+o.id);else for(auto &n:a.actors)combo->addItem(a.name+" / "+n.name,a.id+" "+n.id);}else if(type=="objectEvent")combo->addItems({"interact","hit"});else if(type=="npcEvent")combo->addItems({"interact","hit","defeat"});else if(type=="menu"){for(auto &s:project.scenes)if(s.kind=="screen")combo->addItem(s.name+" ["+s.id+"]",s.id);}else if(type=="keyboard"){for(auto &k:project.keyboards)combo->addItem(k.name+" ["+k.id+"]",k.id);}else if(type=="textField"){for(auto &t:project.textFields)combo->addItem(t.id,t.id);}else if(type=="slot"){for(int n=1;n<=project.saveConfig.slotCount;++n)combo->addItem(QString::number(n));}else if(type=="scene")for(auto &s:project.scenes)combo->addItem(s.name+"  ["+s.id+"]",s.id);else if(type=="script")for(auto &s:project.scripts)combo->addItem(s.name+"  ["+s.id+"]",s.id);else if(type=="timer")for(auto &t:project.timers)combo->addItem(t.name+"  ["+t.id+"]",t.id);else if(type=="comparison")combo->addItems({"==","!=","<","<=",">",">="});else if(type=="sound"){combo->addItems({"blip","hit","chime","pulse","alarm"});for(auto &s:project.sounds)combo->addItem(s.name+" ["+s.id+"]",s.id);}else if(type=="timerAction")combo->addItems({"start","stop","reset"});form->addRow(label,combo);fields<<combo;};
if(key=="set"||key=="add"||key=="sub"){field("Variable","variable");field("Value / variable","value");}if(key=="random"){field("Store result in","variable");field("Minimum (inclusive)","bound");field("Maximum (inclusive)","bound");}if(key=="seed")field("Seed (0–65535) / variable","seed");if(key=="give"||key=="take"){field("Storage","storage");field("Item","item");field("Quantity / variable","value");}if(key=="move"){field("From storage","storage");field("To storage","storage");field("Item","item");field("Quantity / variable","value");}if(key=="open"||key=="view")field("Storage","storage");if(key=="dialogue")field("Prompt","prompt");if(key=="area")field("Area","area");if(key=="object"||key=="npc"){field("Target",key=="object"?"objectRef":"npcRef");field("Event",key=="object"?"objectEvent":"npcEvent");}if(key=="scene")field("Scene","scene");if(key=="call")field("Script","script");if(key=="timer"){field("Action","timerAction");field("Timer","timer");}if(key=="if"){field("Variable","readVariable");field("Comparison","comparison");field("Value / variable","value");}if(key=="if has"){field("Storage","storage");field("Item","item");field("Comparison","comparison");field("Value / variable","value");}
if(key=="menu")field("Menu screen","menu");if(key=="keyboard"){field("Keyboard layout","keyboard");field("Return input to","textField");field("Maximum characters","limit");}if(key.startsWith("save "))field("Save slot","slot");if(key=="text clear")field("Text field","textField");if(key=="text copy"){field("Destination","textField");field("Source","textField");}
if(key=="sound play"||key=="sound loop")field("Sound","sound");
hint->setText(key=="timer"?"Start schedules a full interval. Stop pauses execution. Reset restores the interval and leaves the timer stopped. Create timers in Project & game data.":key=="seed"?"Fixed seeds reproduce the same sequence. Seed 0 uses the default nonzero seed. Random ranges are inclusive.":key.startsWith("if")?"Inserts an if/end block. Put events inside it; add Else when needed. Fields use current project IDs.":"Insert into the active event script at its text cursor. The script remains editable; invalid references are reported before insertion.");};QObject::connect(command,&QComboBox::currentIndexChanged,&dialog,fill);command->setCurrentIndex(branch?14:0);fill();QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{QString key=keys[command->currentIndex()],text=key;for(auto *field:fields){QString value=field->currentData().isValid()?field->currentData().toString():field->currentText().trimmed();if(value.isEmpty()){hint->setText("Create/select the required project entry first.");return;}text+=" "+value;}if(key.startsWith("if"))text+="\n  # events\nend";if(key!="else"&&key!="end"){QVector<CFInstruction> code;QString error;if(!GameCompiler(project).program(text,code,error)){hint->setText(error);return;}}auto cursor=source->textCursor();if(cursor.position()>0&&source->toPlainText().at(cursor.position()-1)!=QChar('\n'))text.prepend('\n');int start=cursor.position();cursor.insertText(text+"\n");if(text.contains("# events"))cursor.setPosition(start+text.indexOf("# events"));source->setTextCursor(cursor);source->setFocus();dialog.accept();});dialog.exec();};QObject::connect(insert,&QPushButton::clicked,widget,[open]{open(false);});QObject::connect(condition,&QPushButton::clicked,widget,[open]{open(true);});QObject::connect(check,&QPushButton::clicked,widget,[source,provider]{QVector<CFInstruction> code;QString error;bool valid=GameCompiler(provider()).program(source->toPlainText(),code,error);QMessageBox::information(source,"Script check",valid?QString("Valid · %1 expanded instructions / 96").arg(code.size()):error);});return widget;}
QWidget *behaviorTools(QPlainTextEdit *source,std::function<Project()> provider,std::function<bool()> isPlayer){auto *widget=new QWidget;auto *layout=new QVBoxLayout(widget);layout->setContentsMargins(0,0,0,0);auto *configure=new QPushButton("Behavior & animation fields…");layout->addWidget(configure);layout->addWidget(source);QObject::connect(configure,&QPushButton::clicked,widget,[source,provider,isPlayer]{auto project=provider();BehaviorSpec b;QString error;parseBehavior(source->toPlainText(),b,error);QDialog dialog(source);dialog.setWindowTitle("Character behavior");auto *form=new QFormLayout(&dialog);auto *kind=new QComboBox;if(isPlayer&&isPlayer())kind->addItem("top_down");else kind->addItems({"idle","patrol","chase"});QStringList kinds{"idle","top_down","patrol","chase"};kind->setCurrentText(isPlayer&&isPlayer()?QString("top_down"):kinds.value(b.code.kind,"idle"));form->addRow("Behavior",kind);auto number=[&](QString name,int value,int max){auto *s=new QSpinBox;s->setRange(1,max);s->setValue(value);form->addRow(name,s);return s;};auto *speed=number("Speed (pixels/update)",b.code.speed,2),*every=number("Update interval (ticks)",b.code.interval,8),*range=number("Patrol range (pixels)",b.code.range,255),*sight=number("Chase sight (pixels)",b.code.sight,255);auto *axis=new QComboBox;axis->addItems({"x","y"});axis->setCurrentIndex(b.code.axis);form->addRow("Patrol axis",axis);auto *touch=new QComboBox;touch->addItem("None","none");for(auto &p:project.prompts)touch->addItem(p.title+" ["+p.id+"]",p.id);touch->setCurrentIndex(qMax(0,touch->findData(b.prompt)));form->addRow("On contact dialogue",touch);QStringList names{"none"};for(auto &asset:project.assets)for(auto &clip:asset.animations)if(!names.contains(clip.name))names<<clip.name;auto clip=[&](QString label,QString value){auto *combo=new QComboBox;combo->addItems(names);combo->setCurrentText(value.isEmpty()?"none":value);form->addRow(label,combo);return combo;};auto *base=clip("Base animation",b.animation),*moving=clip("On moving",b.moveAnimation),*idle=clip("On idle",b.idleAnimation),*action=clip("On interaction",b.actionAnimation);auto *mode=new QComboBox;mode->addItem("Single (one move / idle sprite)","single");mode->addItem("Directional (up / down / left / right)","directional");mode->setCurrentIndex(b.directional?1:0);form->addRow("Movement sprites",mode);
QStringList dirNames{"up","down","left","right"};QVector<QComboBox *>moveDir,idleDir;for(int d=0;d<4;++d){moveDir<<clip("Moving "+dirNames[d],b.moveDir[d]);}for(int d=0;d<4;++d){idleDir<<clip("Idle "+dirNames[d],b.idleDir[d]);}
auto syncMode=[=]{bool on=mode->currentData().toString()=="directional";moving->setEnabled(!on);idle->setEnabled(!on);for(auto *c:moveDir)c->setEnabled(on);for(auto *c:idleDir)c->setEnabled(on);};QObject::connect(mode,&QComboBox::currentIndexChanged,&dialog,syncMode);syncMode();
auto *h=new QCheckBox("Mirror horizontally"),*v=new QCheckBox("Mirror vertically"),*facing=new QCheckBox("Mirror when facing left");h->setChecked(b.code.flags&1);v->setChecked(b.code.flags&2);facing->setChecked(b.code.flags&4);form->addRow(h);form->addRow(v);form->addRow(facing);auto *help=new QLabel("Animation names must exist on this character's sprite. These fields write the same commands available in the source editor.");help->setWordWrap(true);form->addRow(help);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form->addRow(buttons);QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{source->setPlainText(QString("behavior %1\nspeed %2\nevery %3\naxis %4\nrange %5\nsight %6\non_touch %7\nanimation %8\non_move %9\non_idle %10\non_interact %11\nflip_h %12\nflip_v %13\nmirror_facing %14\n").arg(kind->currentText()).arg(speed->value()).arg(every->value()).arg(axis->currentText()).arg(range->value()).arg(sight->value()).arg(touch->currentData().toString(),base->currentText(),moving->currentText(),idle->currentText(),action->currentText(),h->isChecked()?"yes":"no",v->isChecked()?"yes":"no",facing->isChecked()?"yes":"no"));if(mode->currentData().toString()=="directional"){QString text=source->toPlainText()+"movement_sprites directional\n";for(int d=0;d<4;++d)text+=QString("on_move_%1 %2\non_idle_%1 %3\n").arg(dirNames[d],moveDir[d]->currentText(),idleDir[d]->currentText());source->setPlainText(text);}dialog.accept();});dialog.exec();});return widget;}
